const logo = `<img class="brand-mark" src="/assets/images/useful-math-tools-icon.png" width="42" height="42" alt=""><span>Useful Math Tools</span>`;
function header(){return `<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="shell header-row"><a class="brand" href="/">${logo}</a><button class="menu-button" type="button" aria-expanded="false" aria-controls="site-nav" data-menu-button>Menu</button><nav class="nav" id="site-nav" aria-label="Main navigation" data-nav><a href="/#calculators">Calculators</a><a href="/#categories">Categories</a><a href="/history/">History</a><a href="/about/">About</a></nav></div></header>`}
function footer(){return `<footer class="site-footer"><div class="shell"><div class="footer-grid"><section><h2>Useful Math Tools</h2><p>Simple calculators for everyday problems.</p></section><section><h3>Categories</h3><ul><li><a href="/date-time/">Dates &amp; Time</a></li><li><a href="/percentages/">Percentages</a></li><li><a href="/everyday-math/">Everyday Math</a></li><li><a href="/money/">Money</a></li><li><a href="/conversions/">Conversions</a></li><li><a href="/home/">Home &amp; DIY</a></li></ul></section><section><h3>Site</h3><ul><li><a href="/history/">Calculation history</a></li><li><a href="/about/">About</a></li><li><a href="/privacy/">Privacy</a></li><li><a href="/terms/">Terms</a></li></ul></section><section><h3>Common tools</h3><ul><li><a href="/date-time/days-between-dates/">Days between dates</a></li><li><a href="/percentages/percentage-calculator/">Percentage calculator</a></li><li><a href="/money/loan-payment-calculator/">Loan payment</a></li></ul></section></div><div class="copyright">© <span data-year>2026</span> Useful Math Tools</div></div></footer>`}
function head({title,desc,path,json=''}){const url=domain+path;return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><meta name="description" content="${desc}"><link rel="canonical" href="${url}"><meta property="og:title" content="${title}"><meta property="og:description" content="${desc}"><meta property="og:url" content="${url}"><meta property="og:site_name" content="Useful Math Tools"><meta property="og:type" content="website"><meta name="theme-color" content="#087f72"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" href="/favicon-32x32.png" type="image/png" sizes="32x32"><link rel="icon" href="/favicon-16x16.png" type="image/png" sizes="16x16"><link rel="apple-touch-icon" href="/apple-touch-icon.png" sizes="180x180"><link rel="manifest" href="/site.webmanifest"><link rel="stylesheet" href="/assets/css/site.css?v=20261001-brand">${json}</head><body>`}
function breadcrumbs(items){return `<nav class="breadcrumbs" aria-label="Breadcrumb">${items.map((x,i)=>i===items.length-1?`<span aria-current="page">${x[0]}</span>`:`<a href="${x[1]}">${x[0]}</a><span aria-hidden="true">›</span>`).join('')}</nav>`}
function breadcrumbJson(items){return `<script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:items.map((x,i)=>({'@type':'ListItem',position:i+1,name:x[0],item:domain+x[1]}))})}</script>`}
const toolBySlug=Object.fromEntries(tools.map(tool=>[tool.slug,tool]));
function related(tool){const ids=CALCULATOR_BY_ID[tool.slug]?.related||[];const peers=ids.map(id=>toolBySlug[id]).filter(Boolean);return `<div class="related-grid">${peers.map(t=>`<a href="/${t.cat}/${t.slug}/">${t.title}</a>`).join('')}</div>`}
const exampleLabels={'days-between':'Jan 1 → Mar 31','percentage':'What is 20% of 150?','compound':'$10,000 at 5% for 10 years','paint':'12 × 15 ft room','sales-tax':'$100 at 8.25% tax','markup-margin':'$80 cost → $100 price'};
