function calculatorPage(tool){const cat=categories[tool.cat];const path=`/${tool.cat}/${tool.slug}/`;const crumbs=[['Home','/'],[cat.name,`/${tool.cat}/`],[tool.title,path]];const example=exampleLabels[tool.type]?`<div class="example-bar"><span>Try an example:</span><button type="button" class="example-button" data-example>${exampleLabels[tool.type]}</button></div>`:'';return `${head({title:`${tool.title} | Useful Math Tools`,desc:tool.desc,path,json:breadcrumbJson(crumbs)})}${header()}<main id="main"><section class="page-hero"><div class="shell">${breadcrumbs(crumbs)}<div class="title-row"><div><p class="eyebrow">${cat.name}</p><h1 class="page-title">${tool.title}</h1></div>${toolBrandActions}</div><p class="lede">${tool.desc}</p></div></section><div class="shell calculator-layout" data-calculator="${tool.type}" data-calculator-id="${tool.slug}"><section class="calculator-card" aria-label="Calculator">${example}<form novalidate><div class="form-grid">${tool.form}</div><p class="error" data-error role="alert"></p><div class="button-row"><button class="button primary" type="submit">Calculate</button><button class="button secondary" type="reset">Reset</button></div></form></section><aside class="result-card" aria-live="polite"><p class="eyebrow">Result</p><div class="primary-result" id="primary-result" data-result>—</div><div data-result-details><p class="result-note">Enter your values, then select Calculate.</p></div><div class="result-actions"><button class="button" type="button" data-copy-result disabled>Copy result</button><button class="button" type="button" data-copy-link disabled>Copy calculation link</button><button class="button" type="button" data-share-result hidden>Share result</button><span class="action-feedback" data-action-feedback role="status"></span></div></aside></div><article class="shell content">${tool.notice?`<p class="notice">${tool.notice}</p>`:''}<h2>How to use this calculator</h2><p>Enter the requested values, review any options that affect the calculation, and select <strong>Calculate</strong>. The main answer appears beside the form, with supporting details below it.</p><h2>How the calculation works</h2><p class="formula">${tool.formula}</p><h2>Example</h2><p>${tool.example}</p><h2>Related calculators</h2>${related(tool)}<h2>Frequently asked questions</h2>${tool.faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</article></main>${footer()}<script type="module" src="/assets/js/site.js"></script><script type="module" src="/assets/js/calculators.js"></script></body></html>`}

function home(){const featured=new Set(['take-home-pay-estimator','household-budget-calculator','days-between-dates','percentage-calculator','loan-payment-calculator','compound-interest-calculator']);const cards=tools.map(t=>`<article class="tool-card" data-calculator-id="${t.slug}" data-featured="${featured.has(t.slug)}"${featured.has(t.slug)?'':' hidden'}><span class="eyebrow">${categories[t.cat].name}</span><h3>${t.title}</h3><p>${t.desc}</p><a href="/${t.cat}/${t.slug}/">Open calculator</a></article>`).join('');const org=`<script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':'WebSite',name:'Useful Math Tools',url:domain+'/'})}</script>`;return `${head({title:'Useful Math Tools | Calculators for Everyday Problems',desc:'Free, clear calculators for dates, percentages, money, conversions, and everyday math.',path:'/',json:org})}${header()}<main id="main"><section class="hero"><div class="shell hero-grid"><div><p class="eyebrow">Useful math for everyday problems</p><h1>Useful calculators for everyday problems</h1><p>Calculate dates, percentages, money, measurements, and other everyday math quickly and clearly.</p><div class="search-box"><label for="tool-search">Find a calculator</label><input id="tool-search" type="search" placeholder="Try “date”, “percent”, “sale”, or “interest”" data-tool-search><small>Search all 25 calculators by name or everyday phrase.</small></div></div><div class="hero-brand-art"><img src="/assets/images/useful-math-tools-logo.png" alt="Useful Math Tools — Calculators for Everyday Life"></div></div></section><section class="compact-tools" data-saved-section hidden><div class="shell"><div class="compact-heading"><h2>Your saved tools</h2></div><div class="compact-grid" data-saved-tools></div></div></section><section class="compact-tools" data-recent-section hidden><div class="shell"><div class="compact-heading"><h2>Recently used</h2><button class="text-button" type="button" data-clear-recent>Clear recent tools</button></div><div class="compact-grid" data-recent-tools></div></div></section><section class="section" id="calculators"><div class="shell"><div class="section-heading"><div><p class="eyebrow">Start here</p><h2>Common calculations</h2></div><p>Search all 25 tools or start with one of these broadly useful calculators.</p></div><div class="featured-grid">${cards}</div><p class="search-empty" data-search-empty hidden>No calculators matched that search.</p></div></section><section class="section alt" id="categories"><div class="shell"><div class="section-heading"><div><p class="eyebrow">Browse by subject</p><h2>Calculator categories</h2></div></div><div class="category-grid">${Object.entries(categories).map(([slug,c])=>`<section class="category-block"><h2>${c.name}</h2><p>${c.desc}</p><ul class="link-list">${tools.filter(t=>t.cat===slug).map(t=>`<li><a href="/${t.cat}/${t.slug}/">${t.title}</a></li>`).join('')}</ul><a href="/${slug}/">View ${c.name} overview</a></section>`).join('')}</div></div></section><section class="section"><div class="shell content"><h2>Clear answers, useful context</h2><p>Each calculator keeps the main answer easy to find and provides the assumptions or formula needed to understand it. Favorites, recent tools, and calculation history stay in this browser and require no account.</p></div></section></main>${footer()}<script type="module" src="/assets/js/site.js"></script><script type="module" src="/assets/js/home.js"></script></body></html>`}
function hub(slug){const cat=categories[slug],items=tools.filter(t=>t.cat===slug),path=`/${slug}/`,crumbs=[['Home','/'],[cat.name,path]];return `${head({title:`${cat.name} Calculators | Useful Math Tools`,desc:`${cat.desc} Browse every available ${cat.name.toLowerCase()} calculator.`,path,json:breadcrumbJson(crumbs)})}${header()}<main id="main"><section class="page-hero"><div class="shell">${breadcrumbs(crumbs)}<p class="eyebrow">Calculator category</p><h1 class="page-title">${cat.name}</h1><p class="lede">${cat.desc}</p></div></section><section class="shell content"><div class="hub-list">${items.map(t=>`<article class="hub-item"><h2><a href="/${t.cat}/${t.slug}/">${t.title}</a></h2><p>${t.desc}</p></article>`).join('')}</div></section></main>${footer()}<script type="module" src="/assets/js/site.js"></script></body></html>`}
function infoPage(path,title,desc,body){const crumbs=[['Home','/'],[title,`/${path}/`]];return `${head({title:`${title} | Useful Math Tools`,desc,path:`/${path}/`,json:breadcrumbJson(crumbs)})}${header()}<main id="main"><section class="page-hero"><div class="shell">${breadcrumbs(crumbs)}<h1 class="page-title">${title}</h1><p class="lede">${desc}</p></div></section><article class="shell content">${body}</article></main>${footer()}<script type="module" src="/assets/js/site.js"></script></body></html>`}
function historyPage(){const crumbs=[['Home','/'],['Calculation History','/history/']];return `${head({title:'Calculation History | Useful Math Tools',desc:'Reopen, copy, or clear calculations saved locally in this browser.',path:'/history/',json:breadcrumbJson(crumbs)})}${header()}<main id="main"><section class="page-hero"><div class="shell">${breadcrumbs(crumbs)}<h1 class="page-title">Calculation history</h1><p class="lede">Recent calculations saved only in this browser.</p></div></section><section class="shell content"><div class="history-settings"><label class="check"><input type="checkbox" data-history-setting> Save recent calculations</label><button class="button secondary" type="button" data-clear-history>Clear calculation history</button></div><p class="muted">Calculation history is stored only on this device. You can turn it off or clear it at any time.</p><div class="history-list" data-history-list></div><div data-history-empty hidden><h2>No saved calculations</h2><p>Your valid calculations will appear here when history is enabled.</p><div class="related-grid"><a href="/percentages/percentage-calculator/">Percentage Calculator</a><a href="/date-time/days-between-dates/">Days Between Dates</a><a href="/money/loan-payment-calculator/">Loan Payment</a></div></div></section></main>${footer()}<script type="module" src="/assets/js/site.js"></script><script type="module" src="/assets/js/history.js"></script></body></html>`}

