files.set('about/index.html',infoPage('about','About','Clear, free calculators for the numbers that come up in everyday life.',`<h2>Useful answers, clearly explained</h2><p>Useful Math Tools provides free calculators for everyday problems involving dates, percentages, money, measurements, and more. Each tool is designed to give a clear answer while showing enough information to understand the calculation.</p><p>The calculators run in your browser. No account is required.</p><h2>Our approach</h2><p>We prioritize correct calculations, plain language, transparent assumptions, and pages that are comfortable to use on phones and computers.</p>`));
files.set('privacy/index.html',infoPage('privacy','Privacy','How Useful Math Tools handles calculator inputs and browser-side features.',`<p><strong>Last updated: September 29, 2026.</strong></p><h2>Calculator inputs</h2><p>Calculator inputs are generally processed in your browser and are not sent to a custom Useful Math Tools server for calculation. You do not need an account.</p><h2>Information saved on this device</h2><p>If your browser permits local storage, the site may save calculator IDs for favorites and recently used tools, concise calculation-history entries, shareable calculation links, and your history preference. This information is not encrypted and remains in the browser profile on this device unless you clear it.</p><p>The local storage keys are <code>umt:favorites</code>, <code>umt:recentTools</code>, <code>umt:calculationHistory</code>, and <code>umt:settings</code>, and, only when budget saving is enabled, <code>umt:householdBudget</code>. Saved budget values remain in this browser and can be cleared from the budget calculator or privacy page. No hidden user identifier is stored.</p><p><button class="button secondary" type="button" data-clear-site-data>Clear saved calculator data</button> <span class="action-feedback" data-clear-feedback role="status"></span></p><h2>Hosting and technical data</h2><p>The website is delivered through hosting and network infrastructure, including Cloudflare. Those providers may process ordinary technical information such as IP addresses, browser details, requested pages, timestamps, and security signals to deliver and protect the site.</p><h2>Analytics and advertising</h2><p>The site does not currently include custom analytics or advertising scripts. If these services are added, this policy will be updated to explain what is used and what choices are available.</p><h2>Questions and updates</h2><p>This policy may be revised as the site changes. The updated date above will show when the wording was last changed.</p>`));
files.set('history/index.html',historyPage());
files.set('terms/index.html',infoPage('terms','Terms of Use','Plain-language terms for using the calculators and information on this site.',`<p><strong>Last updated: September 29, 2026.</strong></p><h2>Informational use</h2><p>Useful Math Tools provides calculators and explanations for general informational purposes. Results are estimates where assumptions, rounding, rates, coverage, or real-world conditions may vary.</p><h2>Your decisions</h2><p>You are responsible for checking inputs and deciding how to use a result. Financial, legal, tax, health, engineering, regulatory, and other consequential decisions may require advice from a qualified professional or confirmation from the responsible authority.</p><h2>No warranty</h2><p>The site is provided as available without a warranty that every tool is suitable for a particular purpose or that access will always be uninterrupted. We work to make the calculations accurate and clear, but errors can occur.</p><h2>Responsible use</h2><p>Do not misuse the site, interfere with its operation, or attempt to access systems or data without authorization.</p>`));
files.set('404.html',`${head({title:'Page Not Found | Useful Math Tools',desc:'The requested page could not be found. Browse common calculators instead.',path:'/404.html'})}${header()}<main id="main"><section class="page-hero"><div class="shell"><p class="eyebrow">404</p><h1 class="page-title">That page could not be found</h1><p class="lede">The address may be incorrect or the page may have moved.</p></div></section><section class="shell content"><p><a class="button primary" href="/">Return to the homepage</a></p><h2>Common calculators</h2><div class="related-grid"><a href="/date-time/days-between-dates/">Days Between Dates</a><a href="/percentages/percentage-calculator/">Percentage Calculator</a><a href="/money/loan-payment-calculator/">Loan Payment Calculator</a></div></section></main>${footer()}<script type="module" src="/assets/js/site.js"></script></body></html>`);

for(const [path,content] of files){const dest=join(root,path);await mkdir(dirname(dest),{recursive:true});await writeFile(dest,content+'\n');}
